onChange.script:
if origin not in ['Binding','Script']:
	# only update expression if it is different than current expression
	if currentValue.value != self.view.params.alarmProp[self.view.params.propName]['value']:
		propName = self.view.params.propName
		propVal = {'bindType':'Expression','value':currentValue.value}

		logger = system.util.getLogger('configurator.bindingeditor')
		logger.debug('expression created for the expression binding; prop name= ' + propName + '; binding= ' + str(propVal))

		binding = {'propName':propName,'propVal':propVal}

		# updates the alarmProp custom prop on main view (does not change tagConfig; saveBinding must
		# be pressed to add the binding to tagConfig)

		system.perspective.sendMessage("updateBinding",payload={'binding':binding},scope="page")

config.script:
# updating the items displayed in the tree depending on the type of item that
# was clicked on and whether an item was closed/opened (if the item is a
# folder or UDT instance)

currentLevel = {}

self.props.interactable = False

for item in event.itemPath:
	if currentLevel == {}:
		currentLevel = self.props.items[item]
	else:
		currentLevel = currentLevel["items"][item]

itemPath = "/".join(map(str,event.itemPath))

if currentLevel["expanded"] and currentLevel["data"]["hasChildren"]:
	currentLevel["items"] = [{"label":"Fake Item","expanded":False,"data":{},"items":[]}]
else:
	tags = []

	if currentLevel["data"].has_key("folder"):
		baseTagFolder = currentLevel["data"]["folder"]
		if currentLevel["data"].has_key("folder"):
			# folder or udt instance expanded, call browse to get the new items
			results = system.tag.browse(baseTagFolder).getResults()

			for result in results:
				if result["name"] != "_types_":
					if str(result["tagType"]) in ["Folder", "UdtInstance"]:
						tag = {'label': result["name"], 'expanded': False, 'data': {'folder':result["fullPath"], 'hasChildren':result["hasChildren"]}, "items":[]}

						# if the folder/UDT instance has children, add a fake item to make it appear that the tree item has children
						if result["hasChildren"]:
							tag['items'].append({"label":"Fake Item","expanded":False,"data":{},"items":[]})

						tags.append(tag)
					else:
						tags.append({'label': result["name"], 'data': {'tag': result["fullPath"], 'hasChildren':result["hasChildren"]}, 'items': [], 'expanded': False})

			currentLevel["items"] =  tags

# update selection of tree
self.props.selection = [itemPath]
self.props.selectionData = [{"itemPath":itemPath,"value":currentLevel["data"]}]

# if item was expanded when it was clicked, close it; otherwise, expand it
currentLevel["expanded"] = not currentLevel["expanded"]

# tag was selected; grab the tag path and the property name, and send them to propChange

if 'tag' in currentLevel["data"].keys():
	tagPath = currentLevel["data"]["tag"]
	# if the property already had a tag binding, only call propChange if the user
	# selected a different tag
	if tagPath != self.view.params.alarmProp[self.view.params.propName]['value']:
		propName = self.view.params.propName
		propVal = {'bindType':'Tag','value':tagPath}

		logger = system.util.getLogger('configurator.bindingeditor')
		logger.debug('selection for tag binding changed; prop name= ' + propName + '; binding= ' + str(propVal))

		binding = {'propName':propName,'propVal':propVal}

		# updates the alarmProp custom prop on main view (does not change tagConfig; saveBinding must
		# be pressed to add the binding to tagConfig)
		system.perspective.sendMessage("updateBinding",payload={'binding':binding},scope="page")
else:
	tagPath = ''

